using FluentAssertions;
using NexusMods.Paths;

namespace SilverModManager.Games.LoadOrderFile.Tests;

public class XComModOptionsIniFormatTests
{
    private static readonly XComModOptionsIniFormat Format = new();

    [Fact]
    public void EachModIsAnActiveModsLineInTheOrderGiven()
    {
        Format.Render(["Alpha", "Beta"]).Should().Be(
            ";Generated by SilverModManager when the loadout is applied. Changes made here are replaced; reorder the mods on the Load Order page.\n" +
            "[Engine.XComModOptions]\n" +
            "ActiveMods=\"Alpha\"\n" +
            "ActiveMods=\"Beta\"\n");
    }

    [Fact]
    public void NoModsIsTheSectionAlone()
    {
        Format.Render([]).Should().EndWith("[Engine.XComModOptions]\n").And.NotContain("ActiveMods");
    }

    [Theory]
    [InlineData("Cool/Cool.XComMod", "Cool")]
    [InlineData("Cool/cool.xcommod", "Cool")]
    [InlineData("Some Mod/Some Mod.XComMod", "Some Mod")]
    public void AFolderHoldingAnXComModFileNamedAfterItIsAMod(string file, string mod)
    {
        Format.ModOf((RelativePath)file).Should().Be(mod);
    }

    [Theory]
    [InlineData("Cool/Content/a.upk")]
    [InlineData("Cool/Other.XComMod")]
    [InlineData("Cool/Content/Cool.XComMod")]
    [InlineData("Cool.XComMod")]
    [InlineData("DefaultModOptions.ini")]
    public void AnyOtherFileMakesNoFolderAMod(string file)
    {
        Format.ModOf((RelativePath)file).Should().BeNull();
    }

    [Fact]
    public void TheModsAFileListsAreItsActiveModsLinesInOrder()
    {
        var file = ";comment\n[Engine.XComModOptions]\nActiveMods=\"Alpha\"\nActiveMods=\"Some Mod\"\r\nSomethingElse=\"x\"\n";

        Format.Listed(file).Should().Equal("Alpha", "Some Mod");
    }

    [Fact]
    public void ModsListedInAnotherSectionAreNotTheGamesActiveMods()
    {
        Format.Listed("[Other]\nActiveMods=\"Alpha\"\n[Engine.XComModOptions]\nActiveMods=\"Beta\"\n").Should().Equal("Beta");
    }

    [Fact]
    public void AFileWithoutActiveModsListsNothing()
    {
        Format.Listed("[Engine.XComModOptions]\n").Should().BeEmpty();
    }

    [Fact]
    public void WhatRenderWritesListedReadsBack()
    {
        Format.Listed(Format.Render(["Alpha", "Some Mod"])).Should().Equal("Alpha", "Some Mod");
    }
}
